      else if (mord == 2) then
        do i = ie+1, is, -1
          xt = c(i,j)
          if (xt > 0.) then
            qtmp = q1(i-1)
            al_ad(i-1) = al_ad(i-1)-flux_ad(i,j)*(1.-xt)*xt
            al_ad(i) = al_ad(i)+flux_ad(i,j)*(1.-xt)*(1-xt)
            qtmp_ad = qtmp_ad+flux_ad(i,j)*(1+(1.-xt)*((-1)-(-2)*xt))
            xt_ad = xt_ad-flux_ad(i,j)*((1.-xt)*(al(i-1)+al(i)-2*qtmp)+(al(i)-qtmp-xt*(al(i-1)+al(i)-2*qtmp)))
            flux_ad(i,j) = 0.
            q1_ad(i-1) = q1_ad(i-1)+qtmp_ad
            qtmp_ad = 0.
          else
            qtmp = q1(i)
            al_ad(i+1) = al_ad(i+1)+flux_ad(i,j)*(1.+xt)*xt
            al_ad(i) = al_ad(i)+flux_ad(i,j)*(1.+xt)*(1+xt)
            qtmp_ad = qtmp_ad+flux_ad(i,j)*(1+(1.+xt)*((-1)+(-2)*xt))
            xt_ad = xt_ad+flux_ad(i,j)*((1.+xt)*(al(i)+al(i+1)-2*qtmp)+(al(i)-qtmp)+xt*(al(i)+al(i+1)-2*qtmp))
            flux_ad(i,j) = 0.
            q1_ad(i) = q1_ad(i)+qtmp_ad
            qtmp_ad = 0.
          endif
          xt_ad = 0.
        end do
      else if (mord == 3) then
!$taf INCOMPLETE b0,bl,br,hi5,hi6,smt5,smt6,xt1
        do i = is-1, ie+1
          bl(i) = al(i)-q1(i)
          br(i) = al(i+1)-q1(i)
          b0(i) = bl(i)+br(i)
          x0 = abs(b0(i))
          xt = abs(bl(i)-br(i))
          smt5(i) = x0 < xt
          smt6(i) = 3.*x0 < xt
        end do
        do i = is, ie+1
          xt1(i) = c(i,j)
          hi5(i) = smt5(i-1) .and. smt5(i)
          hi6(i) = smt6(i-1) .or. smt6(i)
        end do
        do i = is, ie+1
          if (xt1(i) > 0.) then
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)*(1.-xt1(i))
            q1_ad(i-1) = q1_ad(i-1)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            if (hi6(i)) then
              b0_ad(i-1) = b0_ad(i-1)-fx1_ad(i)*xt1(i)
              br_ad(i-1) = br_ad(i-1)+fx1_ad(i)
              fx1_ad(i) = 0.
            else if (hi5(i)) then
              fx1j = abs(bl(i-1))
              fx1k = abs(br(i-1))
              fx1j_ae = 0.
              fx1k_ad = 0.
              fx1l_ad = fx1_ad(i)*(sign(1.,min(fx1j,fx1k))*sign(1.,br(i-1)))
              fx1j_ae = fx1l_ad*(0.5+sign(0.5,fx1k-fx1j))
              fx1k_ad = fx1l_ad*(0.5-sign(0.5,fx1k-fx1j))
              br_ad(i-1) = br_ad(i-1)+fx1k_ad*sign(1.,br(i-1))
              bl_ad(i-1) = bl_ad(i-1)+fx1j_ae*sign(1.,bl(i-1))
              fx1_ad(i) = 0.
            endif
          else
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)*(1+xt1(i))
            q1_ad(i) = q1_ad(i)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            if (hi6(i)) then
              b0_ad(i) = b0_ad(i)+fx1_ad(i)*xt1(i)
              bl_ad(i) = bl_ad(i)+fx1_ad(i)
              fx1_ad(i) = 0.
            else if (hi5(i)) then
              fx1h = abs(bl(i))
              fx1i = abs(br(i))
              fx1h_ad = 0.
              fx1i_ad = 0.
              fx1j_ad = fx1_ad(i)*(sign(1.,min(fx1h,fx1i))*sign(1.,bl(i)))
              fx1h_ad = fx1j_ad*(0.5+sign(0.5,fx1i-fx1h))
              fx1i_ad = fx1j_ad*(0.5-sign(0.5,fx1i-fx1h))
              br_ad(i) = br_ad(i)+fx1i_ad*sign(1.,br(i))
              bl_ad(i) = bl_ad(i)+fx1h_ad*sign(1.,bl(i))
              fx1_ad(i) = 0.
            endif
          endif
        end do
        do i = is, ie+1
          fx1_ad(i) = 0.
        end do
        do i = is-1, ie+1
          x0_ad = 0.
          xt_ad = 0.
!$taf INCOMPLETE b0,bl,br
          bl(i) = al(i)-q1(i)
          br(i) = al(i+1)-q1(i)
          b0(i) = bl(i)+br(i)
          xtt_ae = 0._8
          xtv_ad = xt_ad
          xtt_ae = xtv_ad*sign(1._8,bl(i)-br(i))
          bl_ad(i) = bl_ad(i)+xtt_ae
          br_ad(i) = br_ad(i)-xtt_ae
          xt_ad = 0.
          x0i_ad = x0_ad
          b0_ad(i) = b0_ad(i)+x0i_ad*sign(1.,b0(i))
          x0_ad = 0.
          bl_ad(i) = bl_ad(i)+b0_ad(i)
          br_ad(i) = br_ad(i)+b0_ad(i)
          b0_ad(i) = 0.
          al_ad(i+1) = al_ad(i+1)+br_ad(i)
          q1_ad(i) = q1_ad(i)-br_ad(i)
          br_ad(i) = 0.
          al_ad(i) = al_ad(i)+bl_ad(i)
          q1_ad(i) = q1_ad(i)-bl_ad(i)
          bl_ad(i) = 0.
        end do
      else if (mord == 4) then
!$taf INCOMPLETE b0,bl,br,hi5,hi6,smt5,smt6,xt1
        do i = is-1, ie+1
          bl(i) = al(i)-q1(i)
          br(i) = al(i+1)-q1(i)
          b0(i) = bl(i)+br(i)
          x0 = abs(b0(i))
          xt = abs(bl(i)-br(i))
          smt5(i) = x0 < xt
          smt6(i) = 3.*x0 < xt
        end do
        do i = is, ie+1
          xt1(i) = c(i,j)
          hi5(i) = smt5(i-1) .and. smt5(i)
          hi6(i) = smt6(i-1) .or. smt6(i)
          hi5(i) = hi5(i) .or. hi6(i)
        end do
        do i = is, ie+1
          if (hi5(i)) then
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)
          endif
          if (xt1(i) > 0.) then
            q1_ad(i-1) = q1_ad(i-1)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i-1) = b0_ad(i-1)-fx1_ad(i)*(1.-xt1(i))*xt1(i)
            br_ad(i-1) = br_ad(i-1)+fx1_ad(i)*(1.-xt1(i))
            fx1_ad(i) = 0.
          else
            q1_ad(i) = q1_ad(i)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i) = b0_ad(i)+fx1_ad(i)*(1.+xt1(i))*xt1(i)
            bl_ad(i) = bl_ad(i)+fx1_ad(i)*(1.+xt1(i))
            fx1_ad(i) = 0.
          endif
        end do
        do i = is-1, ie+1
          x0_ad = 0.
          xt_ad = 0.
!$taf INCOMPLETE b0,bl,br
          bl(i) = al(i)-q1(i)
          br(i) = al(i+1)-q1(i)
          b0(i) = bl(i)+br(i)
          xtt_ad = 0._8
          xtu_ad = xt_ad
          xtt_ad = xtu_ad*sign(1._8,bl(i)-br(i))
          bl_ad(i) = bl_ad(i)+xtt_ad
          br_ad(i) = br_ad(i)-xtt_ad
          xt_ad = 0.
          x0h_ad = x0_ad
          b0_ad(i) = b0_ad(i)+x0h_ad*sign(1.,b0(i))
          x0_ad = 0.
          bl_ad(i) = bl_ad(i)+b0_ad(i)
          br_ad(i) = br_ad(i)+b0_ad(i)
          b0_ad(i) = 0.
          al_ad(i+1) = al_ad(i+1)+br_ad(i)
          q1_ad(i) = q1_ad(i)-br_ad(i)
          br_ad(i) = 0.
          al_ad(i) = al_ad(i)+bl_ad(i)
          q1_ad(i) = q1_ad(i)-bl_ad(i)
          bl_ad(i) = 0.
        end do
      else
!$taf INCOMPLETE b0,bl,br,smt5
        if (mord == 5) then
          do i = is-1, ie+1
            bl(i) = al(i)-q1(i)
            br(i) = al(i+1)-q1(i)
            smt5(i) = bl(i)*br(i) < 0.
          end do
        else
          do i = is-1, ie+1
            bl(i) = al(i)-q1(i)
            br(i) = al(i+1)-q1(i)
            b0(i) = bl(i)+br(i)
            smt5(i) = 3.*abs(b0(i)) < abs(bl(i)-br(i))
          end do
        endif
        do i = is, ie+1
          if (smt5(i-1) .or. smt5(i)) then
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)
          endif
          if (c(i,j) > 0.) then
            q1_ad(i-1) = q1_ad(i-1)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i-1) = b0_ad(i-1)-fx1_ad(i)*(1.-c(i,j))*c(i,j)
            br_ad(i-1) = br_ad(i-1)+fx1_ad(i)*(1.-c(i,j))
            fx1_ad(i) = 0.
          else
            q1_ad(i) = q1_ad(i)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i) = b0_ad(i)+fx1_ad(i)*(1.+c(i,j))*c(i,j)
            bl_ad(i) = bl_ad(i)+fx1_ad(i)*(1.+c(i,j))
            fx1_ad(i) = 0.
          endif
        end do
        if (mord == 5) then
          do i = is-1, ie+1
            bl_ad(i) = bl_ad(i)+b0_ad(i)
            br_ad(i) = br_ad(i)+b0_ad(i)
            b0_ad(i) = 0.
            al_ad(i+1) = al_ad(i+1)+br_ad(i)
            q1_ad(i) = q1_ad(i)-br_ad(i)
            br_ad(i) = 0.
            al_ad(i) = al_ad(i)+bl_ad(i)
            q1_ad(i) = q1_ad(i)-bl_ad(i)
            bl_ad(i) = 0.
          end do
        else
          do i = is-1, ie+1
            bl_ad(i) = bl_ad(i)+b0_ad(i)
            br_ad(i) = br_ad(i)+b0_ad(i)
            b0_ad(i) = 0.
            al_ad(i+1) = al_ad(i+1)+br_ad(i)
            q1_ad(i) = q1_ad(i)-br_ad(i)
            br_ad(i) = 0.
            al_ad(i) = al_ad(i)+bl_ad(i)
            q1_ad(i) = q1_ad(i)-bl_ad(i)
            bl_ad(i) = 0.
          end do
        endif
      endif
      do i = is1, ie3
        al(i) = p1*(q1(i-1)+q1(i))+p2*(q1(i-2)+q1(i+1))
      end do
      if (( .not. nested) .and. grid_type < 3) then
        if (is == 1) then
          al(0) = c1*q1(-2)+c2*q1(-1)+c3*q1(0)
          al(1) = 0.5*(((2.*dxa(0,j)+dxa(-1,j))*q1(0)-dxa(0,j)*q1(-1))/(dxa(-1,j)+dxa(0,j))+((2.*dxa(1,j)+dxa(2,j))*q1(1)-dxa(1,j)*q1(2))/(dxa(1,j)+dxa(2,j)))
          al(2) = c3*q1(1)+c2*q1(2)+c1*q1(3)
        endif
        if (ie+1 == npx) then
          al(npx-1) = c1*q1(npx-3)+c2*q1(npx-2)+c3*q1(npx-1)
          al(npx) = 0.5*(((2.*dxa(npx-1,j)+dxa(npx-2,j))*q1(npx-1)-dxa(npx-1,j)*q1(npx-2))/(dxa(npx-2,j)+dxa(npx-1,j))+((2.*dxa(npx,j)+dxa(npx+1,j))*q1(npx)-dxa(npx,j)*q1(npx+1))/(dxa(npx,j)+dxa(npx+1,j)))
          al(npx+1) = c3*q1(npx)+c2*q1(npx+1)+c1*q1(npx+2)
        endif
      endif
      if (iord < 0) then
        do i = is-1, ie+2
          al_ad(i) = al_ad(i)*(0.5-sign(0.5,0.-al(i)))
        end do
      endif
      if (( .not. nested) .and. grid_type < 3) then
        if (ie+1 == npx) then
          q1_ad(npx+2) = q1_ad(npx+2)+al_ad(npx+1)*c1
          q1_ad(npx+1) = q1_ad(npx+1)+al_ad(npx+1)*c2
          q1_ad(npx) = q1_ad(npx)+al_ad(npx+1)*c3
          al_ad(npx+1) = 0.
          q1_ad(npx-2) = q1_ad(npx-2)-0.5*al_ad(npx)*(dxa(npx-1,j)/(dxa(npx-2,j)+dxa(npx-1,j)))
          q1_ad(npx-1) = q1_ad(npx-1)+0.5*al_ad(npx)*((2.*dxa(npx-1,j)+dxa(npx-2,j))/(dxa(npx-2,j)+dxa(npx-1,j)))
          q1_ad(npx+1) = q1_ad(npx+1)-0.5*al_ad(npx)*(dxa(npx,j)/(dxa(npx,j)+dxa(npx+1,j)))
          q1_ad(npx) = q1_ad(npx)+0.5*al_ad(npx)*((2.*dxa(npx,j)+dxa(npx+1,j))/(dxa(npx,j)+dxa(npx+1,j)))
          al_ad(npx) = 0.
          q1_ad(npx-3) = q1_ad(npx-3)+al_ad(npx-1)*c1
          q1_ad(npx-2) = q1_ad(npx-2)+al_ad(npx-1)*c2
          q1_ad(npx-1) = q1_ad(npx-1)+al_ad(npx-1)*c3
          al_ad(npx-1) = 0.
        endif
        if (is == 1) then
          q1_ad(3) = q1_ad(3)+al_ad(2)*c1
          q1_ad(2) = q1_ad(2)+al_ad(2)*c2
          q1_ad(1) = q1_ad(1)+al_ad(2)*c3
          al_ad(2) = 0.
          q1_ad(2) = q1_ad(2)-0.5*al_ad(1)*(dxa(1,j)/(dxa(1,j)+dxa(2,j)))
          q1_ad(1) = q1_ad(1)+0.5*al_ad(1)*((2.*dxa(1,j)+dxa(2,j))/(dxa(1,j)+dxa(2,j)))
          q1_ad(0) = q1_ad(0)+0.5*al_ad(1)*((2.*dxa(0,j)+dxa(-1,j))/(dxa(-1,j)+dxa(0,j)))
          q1_ad(-1) = q1_ad(-1)-0.5*al_ad(1)*(dxa(0,j)/(dxa(-1,j)+dxa(0,j)))
          al_ad(1) = 0.
          q1_ad(0) = q1_ad(0)+al_ad(0)*c3
          q1_ad(-1) = q1_ad(-1)+al_ad(0)*c2
          q1_ad(-2) = q1_ad(-2)+al_ad(0)*c1
          al_ad(0) = 0.
        endif
      endif
      do i = is1, ie3
        q1_ad(i-2) = q1_ad(i-2)+al_ad(i)*p2
        q1_ad(i-1) = q1_ad(i-1)+al_ad(i)*p1
        q1_ad(i+1) = q1_ad(i+1)+al_ad(i)*p2
        q1_ad(i) = q1_ad(i)+al_ad(i)*p1
        al_ad(i) = 0.
      end do
    else
!$taf INCOMPLETE al,bl,br,dm,dq
      do i = is-2, ie+2
        xt = 0.25*(q1(i+1)-q1(i-1))
        dm(i) = sign(min(abs(xt),max(q1(i-1),q1(i),q1(i+1))-q1(i),q1(i)-min(q1(i-1),q1(i),q1(i+1))),xt)
      end do
      do i = is1, ie1+1
        al(i) = 0.5*(q1(i-1)+q1(i))+r3*(dm(i-1)-dm(i))
      end do
      if (iord == 8) then
        do i = is1, ie1
          xt = 2.*dm(i)
          bl(i) = -sign(min(abs(xt),abs(al(i)-q1(i))),xt)
          br(i) = sign(min(abs(xt),abs(al(i+1)-q1(i))),xt)
        end do
      else if (iord == 11) then
        do i = is1, ie1
          xt = ppm_fac*dm(i)
          bl(i) = -sign(min(abs(xt),abs(al(i)-q1(i))),xt)
          br(i) = sign(min(abs(xt),abs(al(i+1)-q1(i))),xt)
        end do
      else
        do i = is1-2, ie1+1
          dq(i) = 2.*(q1(i+1)-q1(i))
        end do
        do i = is1, ie1
          bl(i) = al(i)-q1(i)
          br(i) = al(i+1)-q1(i)
          if (abs(dm(i-1))+abs(dm(i))+abs(dm(i+1)) < near_zero) then
            bl(i) = 0.
            br(i) = 0.
          else if (abs(3.*(bl(i)+br(i))) > abs(bl(i)-br(i))) then
            pmp_2 = dq(i-1)
            lac_2 = pmp_2-0.75*dq(i-2)
            br(i) = min(max(0.,pmp_2,lac_2),max(br(i),min(0.,pmp_2,lac_2)))
            pmp_1 = -dq(i)
            lac_1 = pmp_1+0.75*dq(i+1)
            bl(i) = min(max(0.,pmp_1,lac_1),max(bl(i),min(0.,pmp_1,lac_1)))
          endif
        end do
      endif
      if (iord == 9 .or. iord == 13) then
        help_h = ie1-is1+1
        call pert_ppm( help_h,q1(is1),bl(is1),br(is1),0 )
      endif
      do i = is, ie+1
        if (c(i,j) > 0.) then
          bl_ad(i-1) = bl_ad(i-1)-flux_ad(i,j)*(1.-c(i,j))*c(i,j)
          br_ad(i-1) = br_ad(i-1)+flux_ad(i,j)*(1.-c(i,j))*(1-c(i,j))
          q1_ad(i-1) = q1_ad(i-1)+flux_ad(i,j)
          flux_ad(i,j) = 0.
        else
          bl_ad(i) = bl_ad(i)+flux_ad(i,j)*(1.+c(i,j))*(1+c(i,j))
          br_ad(i) = br_ad(i)+flux_ad(i,j)*(1.+c(i,j))*c(i,j)
          q1_ad(i) = q1_ad(i)+flux_ad(i,j)
          flux_ad(i,j) = 0.
        endif
      end do
!$taf INCOMPLETE bl,br
      if (( .not. nested) .and. grid_type < 3) then
!$taf INCOMPLETE bl,br
        if (is == 1) then
          bl(0) = s14*dm(-1)+s11*(q1(-1)-q1(0))
          xt = 0.5*(((2.*dxa(0,j)+dxa(-1,j))*q1(0)-dxa(0,j)*q1(-1))/(dxa(-1,j)+dxa(0,j))+((2.*dxa(1,j)+dxa(2,j))*q1(1)-dxa(1,j)*q1(2))/(dxa(1,j)+dxa(2,j)))
          xt = max(xt,min(q1(-1),q1(0),q1(1),q1(2)))
          xt = min(xt,max(q1(-1),q1(0),q1(1),q1(2)))
          br(0) = xt-q1(0)
          bl(1) = xt-q1(1)
          xt = s15*q1(1)+s11*q1(2)-s14*dm(2)
          br(1) = xt-q1(1)
          bl(2) = xt-q1(2)
          br(2) = al(3)-q1(2)
          call pert_ppm( 3,q1(0),bl(0),br(0),1 )
        endif
!$taf INCOMPLETE bl,br
        if (ie+1 == npx) then
!$taf INCOMPLETE bl,br
          bl(npx-2) = al(npx-2)-q1(npx-2)
          xt = s15*q1(npx-1)+s11*q1(npx-2)+s14*dm(npx-2)
          br(npx-2) = xt-q1(npx-2)
          bl(npx-1) = xt-q1(npx-1)
          xt = 0.5*(((2.*dxa(npx-1,j)+dxa(npx-2,j))*q1(npx-1)-dxa(npx-1,j)*q1(npx-2))/(dxa(npx-2,j)+dxa(npx-1,j))+((2.*dxa(npx,j)+dxa(npx+1,j))*q1(npx)-dxa(npx,j)*q1(npx+1))/(dxa(npx,j)+dxa(npx+1,j)))
          xt = max(xt,min(q1(npx-2),q1(npx-1),q1(npx),q1(npx+1)))
          xt = min(xt,max(q1(npx-2),q1(npx-1),q1(npx),q1(npx+1)))
          br(npx-1) = xt-q1(npx-1)
          bl(npx) = xt-q1(npx)
          br(npx) = s11*(q1(npx+1)-q1(npx))-s14*dm(npx+1)
          call pert_ppm_ad( 3,q1(npx-2),q1_ad(npx-2),bl(npx-2),bl_ad(npx-2),br(npx-2),br_ad(npx-2),1 )
          dm_ad(npx+1) = dm_ad(npx+1)-br_ad(npx)*s14
          q1_ad(npx+1) = q1_ad(npx+1)+br_ad(npx)*s11
          q1_ad(npx) = q1_ad(npx)-br_ad(npx)*s11
          br_ad(npx) = 0.
          q1_ad(npx) = q1_ad(npx)-bl_ad(npx)
          xt_ad = xt_ad+bl_ad(npx)
          bl_ad(npx) = 0.
          q1_ad(npx-1) = q1_ad(npx-1)-br_ad(npx-1)
