!$taf INCOMPLETE b0,bl,br,smt5,smt6
      do j = js-1, je+1
        do i = ifirst, ilast
          bl(i,j) = al(i,j)-q(i,j)
          br(i,j) = al(i,j+1)-q(i,j)
          b0(i,j) = bl(i,j)+br(i,j)
          x0 = abs(b0(i,j))
          xt = abs(bl(i,j)-br(i,j))
          smt5(i,j) = x0 < xt
          smt6(i,j) = 3.*x0 < xt
        end do
      end do
      do j = js, je+1
!$taf INCOMPLETE hi5,hi6,xt1
        do i = ifirst, ilast
          xt1(i) = c(i,j)
          hi5(i) = smt5(i,j-1) .and. smt5(i,j)
          hi6(i) = smt6(i,j-1) .or. smt6(i,j)
          hi5(i) = hi5(i) .or. hi6(i)
        end do
        do i = ifirst, ilast
          if (hi5(i)) then
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)
          endif
          if (xt1(i) > 0.) then
            q_ad(i,j-1) = q_ad(i,j-1)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i,j-1) = b0_ad(i,j-1)-fx1_ad(i)*(1.-xt1(i))*xt1(i)
            br_ad(i,j-1) = br_ad(i,j-1)+fx1_ad(i)*(1.-xt1(i))
            fx1_ad(i) = 0.
          else
            q_ad(i,j) = q_ad(i,j)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i,j) = b0_ad(i,j)+fx1_ad(i)*(1.+xt1(i))*xt1(i)
            bl_ad(i,j) = bl_ad(i,j)+fx1_ad(i)*(1.+xt1(i))
            fx1_ad(i) = 0.
          endif
        end do
      end do
      do j = js-1, je+1
        x0_ad = 0.
        xt_ad = 0.
        do i = ifirst, ilast
          x0_ad = 0.
          xt_ad = 0.
!$taf INCOMPLETE b0,bl,br
          bl(i,j) = al(i,j)-q(i,j)
          br(i,j) = al(i,j+1)-q(i,j)
          b0(i,j) = bl(i,j)+br(i,j)
          xtt_ad = 0._8
          xtu_ad = xt_ad
          xtt_ad = xtu_ad*sign(1._8,bl(i,j)-br(i,j))
          bl_ad(i,j) = bl_ad(i,j)+xtt_ad
          br_ad(i,j) = br_ad(i,j)-xtt_ad
          xt_ad = 0.
          x0h_ad = x0_ad
          b0_ad(i,j) = b0_ad(i,j)+x0h_ad*sign(1.,b0(i,j))
          x0_ad = 0.
          bl_ad(i,j) = bl_ad(i,j)+b0_ad(i,j)
          br_ad(i,j) = br_ad(i,j)+b0_ad(i,j)
          b0_ad(i,j) = 0.
          al_ad(i,j+1) = al_ad(i,j+1)+br_ad(i,j)
          q_ad(i,j) = q_ad(i,j)-br_ad(i,j)
          br_ad(i,j) = 0.
          al_ad(i,j) = al_ad(i,j)+bl_ad(i,j)
          q_ad(i,j) = q_ad(i,j)-bl_ad(i,j)
          bl_ad(i,j) = 0.
        end do
      end do
    else
!$taf INCOMPLETE b0,bl,br,smt5
      if (mord == 5) then
        do j = js-1, je+1
          do i = ifirst, ilast
            bl(i,j) = al(i,j)-q(i,j)
            br(i,j) = al(i,j+1)-q(i,j)
            smt5(i,j) = bl(i,j)*br(i,j) < 0.
          end do
        end do
      else
        do j = js-1, je+1
          do i = ifirst, ilast
            bl(i,j) = al(i,j)-q(i,j)
            br(i,j) = al(i,j+1)-q(i,j)
            b0(i,j) = bl(i,j)+br(i,j)
            smt5(i,j) = 3.*abs(b0(i,j)) < abs(bl(i,j)-br(i,j))
          end do
        end do
      endif
      do j = je+1, js, -1
        do i = ifirst, ilast
          if (smt5(i,j-1) .or. smt5(i,j)) then
            fx1_ad(i) = fx1_ad(i)+flux_ad(i,j)
          endif
          if (c(i,j) > 0.) then
            q_ad(i,j-1) = q_ad(i,j-1)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i,j-1) = b0_ad(i,j-1)-fx1_ad(i)*(1.-c(i,j))*c(i,j)
            br_ad(i,j-1) = br_ad(i,j-1)+fx1_ad(i)*(1.-c(i,j))
            fx1_ad(i) = 0.
          else
            q_ad(i,j) = q_ad(i,j)+flux_ad(i,j)
            flux_ad(i,j) = 0.
            b0_ad(i,j) = b0_ad(i,j)+fx1_ad(i)*(1.+c(i,j))*c(i,j)
            bl_ad(i,j) = bl_ad(i,j)+fx1_ad(i)*(1.+c(i,j))
            fx1_ad(i) = 0.
          endif
        end do
      end do
      if (mord == 5) then
        do j = js-1, je+1
          do i = ifirst, ilast
            bl_ad(i,j) = bl_ad(i,j)+b0_ad(i,j)
            br_ad(i,j) = br_ad(i,j)+b0_ad(i,j)
            b0_ad(i,j) = 0.
            al_ad(i,j+1) = al_ad(i,j+1)+br_ad(i,j)
            q_ad(i,j) = q_ad(i,j)-br_ad(i,j)
            br_ad(i,j) = 0.
            al_ad(i,j) = al_ad(i,j)+bl_ad(i,j)
            q_ad(i,j) = q_ad(i,j)-bl_ad(i,j)
            bl_ad(i,j) = 0.
          end do
        end do
      else
        do j = js-1, je+1
          do i = ifirst, ilast
            bl_ad(i,j) = bl_ad(i,j)+b0_ad(i,j)
            br_ad(i,j) = br_ad(i,j)+b0_ad(i,j)
            b0_ad(i,j) = 0.
            al_ad(i,j+1) = al_ad(i,j+1)+br_ad(i,j)
            q_ad(i,j) = q_ad(i,j)-br_ad(i,j)
            br_ad(i,j) = 0.
            al_ad(i,j) = al_ad(i,j)+bl_ad(i,j)
            q_ad(i,j) = q_ad(i,j)-bl_ad(i,j)
            bl_ad(i,j) = 0.
          end do
        end do
      endif
    endif
    do j = js1, je3
      do i = ifirst, ilast
        al(i,j) = p1*(q(i,j-1)+q(i,j))+p2*(q(i,j-2)+q(i,j+1))
      end do
    end do
    if (( .not. nested) .and. grid_type < 3) then
      if (js == 1) then
        do i = ifirst, ilast
          al(i,0) = c1*q(i,-2)+c2*q(i,-1)+c3*q(i,0)
          al(i,1) = 0.5*(((2.*dya(i,0)+dya(i,-1))*q(i,0)-dya(i,0)*q(i,-1))/(dya(i,-1)+dya(i,0))+((2.*dya(i,1)+dya(i,2))*q(i,1)-dya(i,1)*q(i,2))/(dya(i,1)+dya(i,2)))
          al(i,2) = c3*q(i,1)+c2*q(i,2)+c1*q(i,3)
        end do
      endif
      if (je+1 == npy) then
        do i = ifirst, ilast
          al(i,npy-1) = c1*q(i,npy-3)+c2*q(i,npy-2)+c3*q(i,npy-1)
          al(i,npy) = 0.5*(((2.*dya(i,npy-1)+dya(i,npy-2))*q(i,npy-1)-dya(i,npy-1)*q(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1))+((2.*dya(i,npy)+dya(i,npy+1))*q(i,npy)-dya(i,npy)*q(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          al(i,npy+1) = c3*q(i,npy)+c2*q(i,npy+1)+c1*q(i,npy+2)
        end do
      endif
    endif
    if (jord < 0) then
      do j = js-1, je+2
        do i = ifirst, ilast
          al_ad(i,j) = al_ad(i,j)*(0.5-sign(0.5,0.-al(i,j)))
        end do
      end do
    endif
    if (( .not. nested) .and. grid_type < 3) then
      if (je+1 == npy) then
        do i = ifirst, ilast
          q_ad(i,npy+2) = q_ad(i,npy+2)+al_ad(i,npy+1)*c1
          q_ad(i,npy+1) = q_ad(i,npy+1)+al_ad(i,npy+1)*c2
          q_ad(i,npy) = q_ad(i,npy)+al_ad(i,npy+1)*c3
          al_ad(i,npy+1) = 0.
          q_ad(i,npy-2) = q_ad(i,npy-2)-0.5*al_ad(i,npy)*(dya(i,npy-1)/(dya(i,npy-2)+dya(i,npy-1)))
          q_ad(i,npy-1) = q_ad(i,npy-1)+0.5*al_ad(i,npy)*((2.*dya(i,npy-1)+dya(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1)))
          q_ad(i,npy+1) = q_ad(i,npy+1)-0.5*al_ad(i,npy)*(dya(i,npy)/(dya(i,npy)+dya(i,npy+1)))
          q_ad(i,npy) = q_ad(i,npy)+0.5*al_ad(i,npy)*((2.*dya(i,npy)+dya(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          al_ad(i,npy) = 0.
          q_ad(i,npy-3) = q_ad(i,npy-3)+al_ad(i,npy-1)*c1
          q_ad(i,npy-2) = q_ad(i,npy-2)+al_ad(i,npy-1)*c2
          q_ad(i,npy-1) = q_ad(i,npy-1)+al_ad(i,npy-1)*c3
          al_ad(i,npy-1) = 0.
        end do
      endif
      if (js == 1) then
        do i = ifirst, ilast
          q_ad(i,3) = q_ad(i,3)+al_ad(i,2)*c1
          q_ad(i,2) = q_ad(i,2)+al_ad(i,2)*c2
          q_ad(i,1) = q_ad(i,1)+al_ad(i,2)*c3
          al_ad(i,2) = 0.
          q_ad(i,2) = q_ad(i,2)-0.5*al_ad(i,1)*(dya(i,1)/(dya(i,1)+dya(i,2)))
          q_ad(i,1) = q_ad(i,1)+0.5*al_ad(i,1)*((2.*dya(i,1)+dya(i,2))/(dya(i,1)+dya(i,2)))
          q_ad(i,0) = q_ad(i,0)+0.5*al_ad(i,1)*((2.*dya(i,0)+dya(i,-1))/(dya(i,-1)+dya(i,0)))
          q_ad(i,-1) = q_ad(i,-1)-0.5*al_ad(i,1)*(dya(i,0)/(dya(i,-1)+dya(i,0)))
          al_ad(i,1) = 0.
          q_ad(i,0) = q_ad(i,0)+al_ad(i,0)*c3
          q_ad(i,-1) = q_ad(i,-1)+al_ad(i,0)*c2
          q_ad(i,-2) = q_ad(i,-2)+al_ad(i,0)*c1
          al_ad(i,0) = 0.
        end do
      endif
    endif
    do j = js1, je3
      do i = ifirst, ilast
        q_ad(i,j-2) = q_ad(i,j-2)+al_ad(i,j)*p2
        q_ad(i,j-1) = q_ad(i,j-1)+al_ad(i,j)*p1
        q_ad(i,j+1) = q_ad(i,j+1)+al_ad(i,j)*p2
        q_ad(i,j) = q_ad(i,j)+al_ad(i,j)*p1
        al_ad(i,j) = 0.
      end do
    end do
  else
!$taf INCOMPLETE al,bl,br,dm,dq
    do j = js-2, je+2
      do i = ifirst, ilast
        xt = 0.25*(q(i,j+1)-q(i,j-1))
        dm(i,j) = sign(min(abs(xt),max(q(i,j-1),q(i,j),q(i,j+1))-q(i,j),q(i,j)-min(q(i,j-1),q(i,j),q(i,j+1))),xt)
      end do
    end do
    do j = js1, je1+1
      do i = ifirst, ilast
        al(i,j) = 0.5*(q(i,j-1)+q(i,j))+r3*(dm(i,j-1)-dm(i,j))
      end do
    end do
    if (jord == 8) then
      do j = js1, je1
        do i = ifirst, ilast
          xt = 2.*dm(i,j)
          bl(i,j) = -sign(min(abs(xt),abs(al(i,j)-q(i,j))),xt)
          br(i,j) = sign(min(abs(xt),abs(al(i,j+1)-q(i,j))),xt)
        end do
      end do
    else if (jord == 11) then
      do j = js1, je1
        do i = ifirst, ilast
          xt = ppm_fac*dm(i,j)
          bl(i,j) = -sign(min(abs(xt),abs(al(i,j)-q(i,j))),xt)
          br(i,j) = sign(min(abs(xt),abs(al(i,j+1)-q(i,j))),xt)
        end do
      end do
    else
      do j = js1-2, je1+1
        do i = ifirst, ilast
          dq(i,j) = 2.*(q(i,j+1)-q(i,j))
        end do
      end do
      do j = js1, je1
        do i = ifirst, ilast
          bl(i,j) = al(i,j)-q(i,j)
          br(i,j) = al(i,j+1)-q(i,j)
          if (abs(dm(i,j-1))+abs(dm(i,j))+abs(dm(i,j+1)) < near_zero) then
            bl(i,j) = 0.
            br(i,j) = 0.
          else if (abs(3.*(bl(i,j)+br(i,j))) > abs(bl(i,j)-br(i,j))) then
            pmp_2 = dq(i,j-1)
            lac_2 = pmp_2-0.75*dq(i,j-2)
            br(i,j) = min(max(0.,pmp_2,lac_2),max(br(i,j),min(0.,pmp_2,lac_2)))
            pmp_1 = -dq(i,j)
            lac_1 = pmp_1+0.75*dq(i,j+1)
            bl(i,j) = min(max(0.,pmp_1,lac_1),max(bl(i,j),min(0.,pmp_1,lac_1)))
          endif
        end do
      end do
    endif
    if (jord == 9 .or. jord == 13) then
      do j = js1, je1
        help_h = ilast-ifirst+1
        call pert_ppm( help_h,q(ifirst,j),bl(ifirst,j),br(ifirst,j),0 )
      end do
    endif
    do j = js, je+1
      do i = ifirst, ilast
        if (c(i,j) > 0.) then
          bl_ad(i,j-1) = bl_ad(i,j-1)-flux_ad(i,j)*(1.-c(i,j))*c(i,j)
          br_ad(i,j-1) = br_ad(i,j-1)+flux_ad(i,j)*(1.-c(i,j))*(1-c(i,j))
          q_ad(i,j-1) = q_ad(i,j-1)+flux_ad(i,j)
          flux_ad(i,j) = 0.
        else
          bl_ad(i,j) = bl_ad(i,j)+flux_ad(i,j)*(1.+c(i,j))*(1+c(i,j))
          br_ad(i,j) = br_ad(i,j)+flux_ad(i,j)*(1.+c(i,j))*c(i,j)
          q_ad(i,j) = q_ad(i,j)+flux_ad(i,j)
          flux_ad(i,j) = 0.
        endif
      end do
    end do
!$taf INCOMPLETE bl,br
    if (( .not. nested) .and. grid_type < 3) then
!$taf INCOMPLETE bl,br
      if (js == 1) then
        do i = ifirst, ilast
          bl(i,0) = s14*dm(i,-1)+s11*(q(i,-1)-q(i,0))
          xt = 0.5*(((2.*dya(i,0)+dya(i,-1))*q(i,0)-dya(i,0)*q(i,-1))/(dya(i,-1)+dya(i,0))+((2.*dya(i,1)+dya(i,2))*q(i,1)-dya(i,1)*q(i,2))/(dya(i,1)+dya(i,2)))
          xt = max(xt,min(q(i,-1),q(i,0),q(i,1),q(i,2)))
          xt = min(xt,max(q(i,-1),q(i,0),q(i,1),q(i,2)))
          br(i,0) = xt-q(i,0)
          bl(i,1) = xt-q(i,1)
          xt = s15*q(i,1)+s11*q(i,2)-s14*dm(i,2)
          br(i,1) = xt-q(i,1)
          bl(i,2) = xt-q(i,2)
          br(i,2) = al(i,3)-q(i,2)
        end do
        help_i = 3*(ilast-ifirst+1)
        call pert_ppm( help_i,q(ifirst,0),bl(ifirst,0),br(ifirst,0),1 )
      endif
!$taf INCOMPLETE bl,br
      if (je+1 == npy) then
!$taf INCOMPLETE bl,br
        do i = ifirst, ilast
          bl(i,npy-2) = al(i,npy-2)-q(i,npy-2)
          xt = s15*q(i,npy-1)+s11*q(i,npy-2)+s14*dm(i,npy-2)
          br(i,npy-2) = xt-q(i,npy-2)
          bl(i,npy-1) = xt-q(i,npy-1)
          xt = 0.5*(((2.*dya(i,npy-1)+dya(i,npy-2))*q(i,npy-1)-dya(i,npy-1)*q(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1))+((2.*dya(i,npy)+dya(i,npy+1))*q(i,npy)-dya(i,npy)*q(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          xt = max(xt,min(q(i,npy-2),q(i,npy-1),q(i,npy),q(i,npy+1)))
          xt = min(xt,max(q(i,npy-2),q(i,npy-1),q(i,npy),q(i,npy+1)))
          br(i,npy-1) = xt-q(i,npy-1)
          bl(i,npy) = xt-q(i,npy)
          br(i,npy) = s11*(q(i,npy+1)-q(i,npy))-s14*dm(i,npy+1)
        end do
        help_j = 3*(ilast-ifirst+1)
        call pert_ppm_ad( help_j,q(ifirst,npy-2),q_ad(ifirst,npy-2),bl(ifirst,npy-2),bl_ad(ifirst,npy-2),br(ifirst,npy-2),br_ad(ifirst,npy-2),1 )
        do i = ifirst, ilast
          xt_ad = 0.
          xt = 0.5*(((2.*dya(i,npy-1)+dya(i,npy-2))*q(i,npy-1)-dya(i,npy-1)*q(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1))+((2.*dya(i,npy)+dya(i,npy+1))*q(i,npy)-dya(i,npy)*q(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          xt = max(xt,min(q(i,npy-2),q(i,npy-1),q(i,npy),q(i,npy+1)))
          dm_ad(i,npy+1) = dm_ad(i,npy+1)-br_ad(i,npy)*s14
          q_ad(i,npy+1) = q_ad(i,npy+1)+br_ad(i,npy)*s11
          q_ad(i,npy) = q_ad(i,npy)-br_ad(i,npy)*s11
          br_ad(i,npy) = 0.
          q_ad(i,npy) = q_ad(i,npy)-bl_ad(i,npy)
          xt_ad = xt_ad+bl_ad(i,npy)
          bl_ad(i,npy) = 0.
          q_ad(i,npy-1) = q_ad(i,npy-1)-br_ad(i,npy-1)
          xt_ad = xt_ad+br_ad(i,npy-1)
          br_ad(i,npy-1) = 0.
          xth = max(q(i,npy-2),q(i,npy-1))
          xti = max(xth,q(i,npy))
          xtj = max(xti,q(i,npy+1))
          xtj_ad = xt_ad*(0.5-sign(0.5,xtj-xt))
          xt_ad = xt_ad*(0.5+sign(0.5,xtj-xt))
          q_ad(i,npy+1) = q_ad(i,npy+1)+xtj_ad*(0.5-sign(0.5,xti-q(i,npy+1)))
          xti_ad = xtj_ad*(0.5+sign(0.5,xti-q(i,npy+1)))
          q_ad(i,npy) = q_ad(i,npy)+xti_ad*(0.5-sign(0.5,xth-q(i,npy)))
          xth_ad = xti_ad*(0.5+sign(0.5,xth-q(i,npy)))
          q_ad(i,npy-2) = q_ad(i,npy-2)+xth_ad*(0.5+sign(0.5,q(i,npy-2)-q(i,npy-1)))
          q_ad(i,npy-1) = q_ad(i,npy-1)+xth_ad*(0.5-sign(0.5,q(i,npy-2)-q(i,npy-1)))
          xt = 0.5*(((2.*dya(i,npy-1)+dya(i,npy-2))*q(i,npy-1)-dya(i,npy-1)*q(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1))+((2.*dya(i,npy)+dya(i,npy+1))*q(i,npy)-dya(i,npy)*q(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          xtk = min(q(i,npy-2),q(i,npy-1))
          xtl = min(xtk,q(i,npy))
          xtm = min(xtl,q(i,npy+1))
          xtm_ad = xt_ad*(0.5-sign(0.5,xt-xtm))
          xt_ad = xt_ad*(0.5+sign(0.5,xt-xtm))
          q_ad(i,npy+1) = q_ad(i,npy+1)+xtm_ad*(0.5-sign(0.5,q(i,npy+1)-xtl))
          xtl_ad = xtm_ad*(0.5+sign(0.5,q(i,npy+1)-xtl))
          q_ad(i,npy) = q_ad(i,npy)+xtl_ad*(0.5-sign(0.5,q(i,npy)-xtk))
          xtk_ad = xtl_ad*(0.5+sign(0.5,q(i,npy)-xtk))
