            fx1(i) = (1.-c(i,j))*(br(i,j-1)-c(i,j)*b0(i,j-1))
            flux_tl(i,j) = q_tl(i,j-1)
            flux(i,j) = q(i,j-1)
          else
            fx1_tl(i) = b0_tl(i,j)*(1.+c(i,j))*c(i,j)+bl_tl(i,j)*(1.+c(i,j))
            fx1(i) = (1.+c(i,j))*(bl(i,j)+c(i,j)*b0(i,j))
            flux_tl(i,j) = q_tl(i,j)
            flux(i,j) = q(i,j)
          endif
          if (smt5(i,j-1) .or. smt5(i,j)) then
            flux_tl(i,j) = flux_tl(i,j)+fx1_tl(i)
            flux(i,j) = flux(i,j)+fx1(i)
          endif
        end do
      end do
    endif
  else
    do j = js-2, je+2
      do i = ifirst, ilast
        xt_tl = (-0.25)*q_tl(i,j-1)+0.25*q_tl(i,j+1)
        xt = 0.25*(q(i,j+1)-q(i,j-1))
        dmh = abs(xt)
        dmi = max(q(i,j-1),q(i,j))
        dmk = max(dmi,q(i,j+1))-q(i,j)
        dml = min(q(i,j-1),q(i,j))
        dmn = q(i,j)-min(dml,q(i,j+1))
        dmo = min(dmh,dmk)
        dmp = min(dmo,dmn)
        dm_tl(i,j) = (((-((q_tl(i,j-1)*(0.5+sign(0.5,q(i,j)-q(i,j-1)))+q_tl(i,j)*(0.5-sign(0.5,q(i,j)-q(i,j-1))))*(0.5+sign(0.5,q(i,j+1)-dml))+q_tl(i,j+1)*(0.5-sign(0.5,q(i,j+1)-dml))))+q_tl(i,j))*(0.5-sign(0.5,dmn-dmo))+(xt_tl*(0.5+sign(0.5,dmk-dmh))*sign(1.,xt)+((q_tl(i,j-1)*(0.5+sign(0.5,q(i,j-1)-q(i,j)))+q_tl(i,j)*(0.5-sign(0.5,q(i,j-1)-q(i,j))))*(0.5+sign(0.5,dmi-q(i,j+1)))+q_tl(i,j+1)*(0.5-sign(0.5,dmi-q(i,j+1)))-q_tl(i,j))*(0.5-sign(0.5,dmk-dmh)))*(0.5+sign(0.5,dmn-dmo)))*(sign(1.,dmp)*sign(1.,xt))
        dm(i,j) = sign(dmp,xt)
      end do
    end do
    do j = js1, je1+1
      do i = ifirst, ilast
        al_tl(i,j) = dm_tl(i,j-1)*r3-dm_tl(i,j)*r3+0.5*q_tl(i,j-1)+0.5*q_tl(i,j)
        al(i,j) = 0.5*(q(i,j-1)+q(i,j))+r3*(dm(i,j-1)-dm(i,j))
      end do
    end do
    if (jord == 8) then
      do j = js1, je1
        do i = ifirst, ilast
          xt_tl = 2*dm_tl(i,j)
          xt = 2.*dm(i,j)
          bln = abs(xt)
          blo = al(i,j)-q(i,j)
          blp = abs(blo)
          blq = min(bln,blp)
          bl_tl(i,j) = -((xt_tl*(0.5+sign(0.5,blp-bln))*sign(1.,xt)+(al_tl(i,j)-q_tl(i,j))*(0.5-sign(0.5,blp-bln))*sign(1._8,blo))*(sign(1.,blq)*sign(1.,xt)))
          bl(i,j) = -sign(blq,xt)
          brm = abs(xt)
          brn = al(i,j+1)-q(i,j)
          bro = abs(brn)
          brp = min(brm,bro)
          br_tl(i,j) = (xt_tl*(0.5+sign(0.5,bro-brm))*sign(1.,xt)+(al_tl(i,j+1)-q_tl(i,j))*(0.5-sign(0.5,bro-brm))*sign(1._8,brn))*(sign(1.,brp)*sign(1.,xt))
          br(i,j) = sign(brp,xt)
        end do
      end do
    else if (jord == 11) then
      do j = js1, je1
        do i = ifirst, ilast
          xt_tl = dm_tl(i,j)*ppm_fac
          xt = ppm_fac*dm(i,j)
          blr = abs(xt)
          bls = al(i,j)-q(i,j)
          blu = abs(bls)
          blv = min(blr,blu)
          bl_tl(i,j) = -((xt_tl*(0.5+sign(0.5,blu-blr))*sign(1.,xt)+(al_tl(i,j)-q_tl(i,j))*(0.5-sign(0.5,blu-blr))*sign(1._8,bls))*(sign(1.,blv)*sign(1.,xt)))
          bl(i,j) = -sign(blv,xt)
          brq = abs(xt)
          brr = al(i,j+1)-q(i,j)
          brs = abs(brr)
          brt = min(brq,brs)
          br_tl(i,j) = (xt_tl*(0.5+sign(0.5,brs-brq))*sign(1.,xt)+(al_tl(i,j+1)-q_tl(i,j))*(0.5-sign(0.5,brs-brq))*sign(1._8,brr))*(sign(1.,brt)*sign(1.,xt))
          br(i,j) = sign(brt,xt)
        end do
      end do
    else
      do j = js1-2, je1+1
        do i = ifirst, ilast
          dq_tl(i,j) = 2*q_tl(i,j+1)-2*q_tl(i,j)
          dq(i,j) = 2.*(q(i,j+1)-q(i,j))
        end do
      end do
      do j = js1, je1
        do i = ifirst, ilast
          bl_tl(i,j) = al_tl(i,j)-q_tl(i,j)
          bl(i,j) = al(i,j)-q(i,j)
          br_tl(i,j) = al_tl(i,j+1)-q_tl(i,j)
          br(i,j) = al(i,j+1)-q(i,j)
          if (abs(dm(i,j-1))+abs(dm(i,j))+abs(dm(i,j+1)) < near_zero) then
            bl_tl(i,j) = 0.
            bl(i,j) = 0.
            br_tl(i,j) = 0.
            br(i,j) = 0.
          else if (abs(3.*(bl(i,j)+br(i,j))) > abs(bl(i,j)-br(i,j))) then
            pmp_2_tl = dq_tl(i,j-1)
            pmp_2 = dq(i,j-1)
            lac_2_tl = (-0.75)*dq_tl(i,j-2)+pmp_2_tl
            lac_2 = pmp_2-0.75*dq(i,j-2)
            brh = max(0.,pmp_2)
            bri = max(brh,lac_2)
            brj = min(0.,pmp_2)
            brk = min(brj,lac_2)
            brl = max(br(i,j),brk)
            br_tl(i,j) = (pmp_2_tl*(0.5-sign(0.5,0.-pmp_2))*(0.5+sign(0.5,brh-lac_2))+lac_2_tl*(0.5-sign(0.5,brh-lac_2)))*(0.5+sign(0.5,brl-bri))+(br_tl(i,j)*(0.5+sign(0.5,br(i,j)-brk))+(pmp_2_tl*(0.5-sign(0.5,pmp_2-0.))*(0.5+sign(0.5,lac_2-brj))+lac_2_tl*(0.5-sign(0.5,lac_2-brj)))*(0.5-sign(0.5,br(i,j)-brk)))*(0.5-sign(0.5,brl-bri))
            br(i,j) = min(bri,brl)
            pmp_1_tl = -dq_tl(i,j)
            pmp_1 = -dq(i,j)
            lac_1_tl = 0.75*dq_tl(i,j+1)+pmp_1_tl
            lac_1 = pmp_1+0.75*dq(i,j+1)
            blh = max(0.,pmp_1)
            bli = max(blh,lac_1)
            blj = min(0.,pmp_1)
            blk = min(blj,lac_1)
            bll = max(bl(i,j),blk)
            bl_tl(i,j) = (pmp_1_tl*(0.5-sign(0.5,0.-pmp_1))*(0.5+sign(0.5,blh-lac_1))+lac_1_tl*(0.5-sign(0.5,blh-lac_1)))*(0.5+sign(0.5,bll-bli))+(bl_tl(i,j)*(0.5+sign(0.5,bl(i,j)-blk))+(pmp_1_tl*(0.5-sign(0.5,pmp_1-0.))*(0.5+sign(0.5,lac_1-blj))+lac_1_tl*(0.5-sign(0.5,lac_1-blj)))*(0.5-sign(0.5,bl(i,j)-blk)))*(0.5-sign(0.5,bll-bli))
            bl(i,j) = min(bli,bll)
          endif
        end do
      end do
    endif
    if (jord == 9 .or. jord == 13) then
      do j = js1, je1
        help_h = ilast-ifirst+1
        call pert_ppm_tl( help_h,q(ifirst,j),q_tl(ifirst,j),bl(ifirst,j),bl_tl(ifirst,j),br(ifirst,j),br_tl(ifirst,j),0 )
      end do
    endif
    if (( .not. nested) .and. grid_type < 3) then
      if (js == 1) then
        do i = ifirst, ilast
          bl_tl(i,0) = dm_tl(i,-1)*s14-q_tl(i,0)*s11+q_tl(i,-1)*s11
          bl(i,0) = s14*dm(i,-1)+s11*(q(i,-1)-q(i,0))
          xt_tl = (-(0.5*q_tl(i,2)*(dya(i,1)/(dya(i,1)+dya(i,2)))))+0.5*q_tl(i,1)*((2.*dya(i,1)+dya(i,2))/(dya(i,1)+dya(i,2)))+0.5*q_tl(i,0)*((2.*dya(i,0)+dya(i,-1))/(dya(i,-1)+dya(i,0)))-0.5*q_tl(i,-1)*(dya(i,0)/(dya(i,-1)+dya(i,0)))
          xt = 0.5*(((2.*dya(i,0)+dya(i,-1))*q(i,0)-dya(i,0)*q(i,-1))/(dya(i,-1)+dya(i,0))+((2.*dya(i,1)+dya(i,2))*q(i,1)-dya(i,1)*q(i,2))/(dya(i,1)+dya(i,2)))
          xtq = min(q(i,-1),q(i,0))
          xtr = min(xtq,q(i,1))
          xts = min(xtr,q(i,2))
          xt_tl = xt_tl*(0.5+sign(0.5,xt-xts))+(q_tl(i,2)*(0.5-sign(0.5,q(i,2)-xtr))+(q_tl(i,1)*(0.5-sign(0.5,q(i,1)-xtq))+(q_tl(i,0)*(0.5-sign(0.5,q(i,0)-q(i,-1)))+q_tl(i,-1)*(0.5+sign(0.5,q(i,0)-q(i,-1))))*(0.5+sign(0.5,q(i,1)-xtq)))*(0.5+sign(0.5,q(i,2)-xtr)))*(0.5-sign(0.5,xt-xts))
          xt = max(xt,xts)
          xtn = max(q(i,-1),q(i,0))
          xto = max(xtn,q(i,1))
          xtp = max(xto,q(i,2))
          xt_tl = xt_tl*(0.5+sign(0.5,xtp-xt))+(q_tl(i,2)*(0.5-sign(0.5,xto-q(i,2)))+(q_tl(i,1)*(0.5-sign(0.5,xtn-q(i,1)))+(q_tl(i,0)*(0.5-sign(0.5,q(i,-1)-q(i,0)))+q_tl(i,-1)*(0.5+sign(0.5,q(i,-1)-q(i,0))))*(0.5+sign(0.5,xtn-q(i,1))))*(0.5+sign(0.5,xto-q(i,2))))*(0.5-sign(0.5,xtp-xt))
          xt = min(xt,xtp)
          br_tl(i,0) = (-q_tl(i,0))+xt_tl
          br(i,0) = xt-q(i,0)
          bl_tl(i,1) = (-q_tl(i,1))+xt_tl
          bl(i,1) = xt-q(i,1)
          xt_tl = (-(dm_tl(i,2)*s14))+q_tl(i,2)*s11+q_tl(i,1)*s15
          xt = s15*q(i,1)+s11*q(i,2)-s14*dm(i,2)
          br_tl(i,1) = (-q_tl(i,1))+xt_tl
          br(i,1) = xt-q(i,1)
          bl_tl(i,2) = (-q_tl(i,2))+xt_tl
          bl(i,2) = xt-q(i,2)
          br_tl(i,2) = al_tl(i,3)-q_tl(i,2)
          br(i,2) = al(i,3)-q(i,2)
        end do
        help_i = 3*(ilast-ifirst+1)
        call pert_ppm_tl( help_i,q(ifirst,0),q_tl(ifirst,0),bl(ifirst,0),bl_tl(ifirst,0),br(ifirst,0),br_tl(ifirst,0),1 )
      endif
      if (je+1 == npy) then
        do i = ifirst, ilast
          bl_tl(i,npy-2) = al_tl(i,npy-2)-q_tl(i,npy-2)
          bl(i,npy-2) = al(i,npy-2)-q(i,npy-2)
          xt_tl = dm_tl(i,npy-2)*s14+q_tl(i,npy-2)*s11+q_tl(i,npy-1)*s15
          xt = s15*q(i,npy-1)+s11*q(i,npy-2)+s14*dm(i,npy-2)
          br_tl(i,npy-2) = (-q_tl(i,npy-2))+xt_tl
          br(i,npy-2) = xt-q(i,npy-2)
          bl_tl(i,npy-1) = (-q_tl(i,npy-1))+xt_tl
          bl(i,npy-1) = xt-q(i,npy-1)
          xt_tl = (-(0.5*q_tl(i,npy-2)*(dya(i,npy-1)/(dya(i,npy-2)+dya(i,npy-1)))))+0.5*q_tl(i,npy-1)*((2.*dya(i,npy-1)+dya(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1)))-0.5*q_tl(i,npy+1)*(dya(i,npy)/(dya(i,npy)+dya(i,npy+1)))+0.5*q_tl(i,npy)*((2.*dya(i,npy)+dya(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          xt = 0.5*(((2.*dya(i,npy-1)+dya(i,npy-2))*q(i,npy-1)-dya(i,npy-1)*q(i,npy-2))/(dya(i,npy-2)+dya(i,npy-1))+((2.*dya(i,npy)+dya(i,npy+1))*q(i,npy)-dya(i,npy)*q(i,npy+1))/(dya(i,npy)+dya(i,npy+1)))
          xtk = min(q(i,npy-2),q(i,npy-1))
          xtl = min(xtk,q(i,npy))
          xtm = min(xtl,q(i,npy+1))
          xt_tl = xt_tl*(0.5+sign(0.5,xt-xtm))+(q_tl(i,npy+1)*(0.5-sign(0.5,q(i,npy+1)-xtl))+(q_tl(i,npy)*(0.5-sign(0.5,q(i,npy)-xtk))+(q_tl(i,npy-2)*(0.5+sign(0.5,q(i,npy-1)-q(i,npy-2)))+q_tl(i,npy-1)*(0.5-sign(0.5,q(i,npy-1)-q(i,npy-2))))*(0.5+sign(0.5,q(i,npy)-xtk)))*(0.5+sign(0.5,q(i,npy+1)-xtl)))*(0.5-sign(0.5,xt-xtm))
          xt = max(xt,xtm)
          xth = max(q(i,npy-2),q(i,npy-1))
          xti = max(xth,q(i,npy))
          xtj = max(xti,q(i,npy+1))
          xt_tl = xt_tl*(0.5+sign(0.5,xtj-xt))+(q_tl(i,npy+1)*(0.5-sign(0.5,xti-q(i,npy+1)))+(q_tl(i,npy)*(0.5-sign(0.5,xth-q(i,npy)))+(q_tl(i,npy-2)*(0.5+sign(0.5,q(i,npy-2)-q(i,npy-1)))+q_tl(i,npy-1)*(0.5-sign(0.5,q(i,npy-2)-q(i,npy-1))))*(0.5+sign(0.5,xth-q(i,npy))))*(0.5+sign(0.5,xti-q(i,npy+1))))*(0.5-sign(0.5,xtj-xt))
          xt = min(xt,xtj)
          br_tl(i,npy-1) = (-q_tl(i,npy-1))+xt_tl
          br(i,npy-1) = xt-q(i,npy-1)
          bl_tl(i,npy) = (-q_tl(i,npy))+xt_tl
          bl(i,npy) = xt-q(i,npy)
          br_tl(i,npy) = (-(dm_tl(i,npy+1)*s14))+q_tl(i,npy+1)*s11-q_tl(i,npy)*s11
          br(i,npy) = s11*(q(i,npy+1)-q(i,npy))-s14*dm(i,npy+1)
        end do
        help_j = 3*(ilast-ifirst+1)
        call pert_ppm_tl( help_j,q(ifirst,npy-2),q_tl(ifirst,npy-2),bl(ifirst,npy-2),bl_tl(ifirst,npy-2),br(ifirst,npy-2),br_tl(ifirst,npy-2),1 )
      endif
    endif
    do j = js, je+1
      do i = ifirst, ilast
        if (c(i,j) > 0.) then
          flux_tl(i,j) = (-(bl_tl(i,j-1)*(1.-c(i,j))*c(i,j)))+br_tl(i,j-1)*(1.-c(i,j))*(1-c(i,j))+q_tl(i,j-1)
          flux(i,j) = q(i,j-1)+(1.-c(i,j))*(br(i,j-1)-c(i,j)*(bl(i,j-1)+br(i,j-1)))
        else
          flux_tl(i,j) = bl_tl(i,j)*(1.+c(i,j))*(1+c(i,j))+br_tl(i,j)*(1.+c(i,j))*c(i,j)+q_tl(i,j)
          flux(i,j) = q(i,j)+(1.+c(i,j))*(bl(i,j)+c(i,j)*(bl(i,j)+br(i,j)))
        endif
      end do
    end do
  endif

  end subroutine yppm_tl
end module     tp_core_mod
